package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	var s string
	fmt.Fscan(in, &s)

	count := 0
	i := 0
	for i < n {
		if s[i] == 'x' {
			j := i
			for j < n && s[j] == 'x' {
				j++
			}
			lenRun := j - i
			if lenRun >= 3 {
				count += lenRun - 2
			}
			i = j
		} else {
			i++
		}
	}

	fmt.Println(count)
}

