import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	var s string
	fmt.Fscan(in, &s)

	count := 0
	consecutiveX := 0

	for i := 0; i < n; i++ {
		if s[i] == 'x' {
			consecutiveX++
			if consecutiveX >= 3 {
				count++
			}
		} else {
			consecutiveX = 0
		}
	}

	fmt.Println(count)
}
